update_rule.pseudocode:
for each household h:
  member_ids = members(h)
  hh_norm = mean(perceived_benefit[m] - perceived_cost[m] for m in member_ids)
  for m in member_ids:
    perceived_benefit[m] = clip(perceived_benefit[m] + household_influence_weight*hh_norm*0.5, 0, 1)
    perceived_cost[m] = clip(perceived_cost[m] - household_influence_weight*hh_norm*0.2, 0, 1)
  // mask sharing
  if household_mask_sharing_probability > 0:
    redistribute masks to minimize number of members with zero masks while not exceeding total hh inventory
    emit signal.mask_sharing_events[h]

for each person i:
  assign today's locations by schedule with probability schedule_adherence
  apply work_from_home_rate: if applied, replace work with home

for each location type T in {home, workplace, school, retailer, public_space}:
  base_contacts = base_daily_contacts * contact_rate_multiplier_T
  for each location L of type T:
    attendees = persons at L today
    sample pairwise contacts ~ Poisson(base_contacts) per person, constrain by capacity and contact_intensity(L)
    add to signal.contacts_today list as tuples (i, j, L.type)

mandate_active = (day >= mandate_active_day)
noncompliance_events = 0
for each location L with policy_requirement if mandate_active:
  for each attendee i at L:
    if not mask_wearing_state[i]:
      if rand() < enforcement_probability * L.enforcement_level:
        noncompliance_events += 1
        if rand() < deny_entry_probability:
          remove i from attendees; record enforcement action
        else:
          enforcement_history[i].fines += fine_amount
emit observable.noncompliance_events_daily = noncompliance_events

new_infections = 0
for each contact (i, j, loc_type) in signal.contacts_today:
  if health_status[i] == 'infectious' and health_status[j] == 'susceptible':
    p = base_transmission_probability
    if mask_wearing_state[i]: p *= (1 - mask_efficacy_source_control)
    if mask_wearing_state[j]: p *= (1 - mask_efficacy_wearer_protection)
    if vaccination_status[j] == 1: p *= (1 - vaccination_effectiveness)
    if Bernoulli(p): health_status[j] = 'exposed'; new_infections += 1
  repeat symmetric direction (j->i)
// Progress disease states (E->I->R) according to incubation/infectious/recovery periods (discrete day counters)
// External infection pressure
for each susceptible s:
  if Bernoulli(external_infection_pressure): health_status[s] = 'exposed'; new_infections += 1
// Estimate Rt using Cori method: Rt = new_infections / sum_{tau=1..w} infections[day-tau]*wgt[tau]
emit observable.infections_daily = new_infections
emit observable.effective_Rt_daily = Rt_estimate
